Ext.define("bcp.view.ChangeRequesterWindowViewController", {
    extend: "Ext.app.ViewController",
    alias: "controller.changerequesterwindow",

    onReqForChange: function (field, newValue, oldValue, eOpts) {
        var record = this.getViewModel().get("record"),
            requesterIdHf = this.lookupReference("requesterIdHf"),
            refs = this.getReferences(),
            onBehalfCombo = refs.onBehalfCombo;

        if (newValue) {
            //depend on user selected radio button, make sure only one requesterId in the form
            //and ui value changes
            if (newValue.whoVal === "notme") {
                requesterIdHf.disable();
                //fix combo disappear the first time when change from self to
                //someone else and start typing in the combo
                onBehalfCombo.enable();
                onBehalfCombo.reset();
                if (record) record.set("requesterId", -1);
            } else {
                //make it the same as creator's id
                if (record) record.set("requesterId", record.get("creatorId"));
                requesterIdHf.enable();
                onBehalfCombo.disable();
            }
        }
    },

    onReqForComboChange: function (field, newValue, oldValue, eOpts) {
        var model = this.getViewModel(),
            record = model.get("record");
        if (field.selection) {
            var sel = field.selection.data;
            //set requester and requestFor;
            record.set("requesterId", sel.peopleId);
            record.set("requesterName", sel.displayName);
        }
    },

    onSave: function (button, e, eOpts) {
        var refs = this.getReferences(),
            model = this.getViewModel(),
            form = refs.form,
            user = model.get("loggedInUser"),
            userId = user.peopleId,
            currentUserDivId = user.divId,
            formData = {},
            routeObj = {},
            rec = {},
            //for update
            method = "PUT",
            url = "",
            needRouteUpdt = false,
            routeStore = Ext.getStore("DefaultRoutes"),
            defaultRouteModel = routeStore.first(),
            defaultRoute = null,
            updateRouteUrl = "",
            me = this;

        if (defaultRouteModel && defaultRouteModel.data) {
            defaultRoute = defaultRouteModel.data;
        }

        // check form Valid only for generalpanel which is a form, other tabs are not forms
        if (form.isValid()) {
            form.updateRecord();
            formData = form.getValues();
            rec = form.getRecord();

            url = bcp.config.Runtime.getServerBaseUrl() + "requests/" + rec.data.requestId;

            formData.creatorId = userId;

            //create for myself
            if (formData.whoVal === "self") {
                //if a NIST Associate
                if (user.staffType !== "NIST Employee") {
                    if (!defaultRoute.host || defaultRoute.host.personId === 0) {
                        Ext.Msg.alert(
                            "Warning",
                            "The system cannot perform this operation because the NIST Host is not defined. " +
                                "Please contact your AO or Office Manager. They can define who is the NIST Host for you " +
                                "using the NIST Org application"
                        );
                        return;
                    } else {
                        rec.set("requesterId", defaultRoute.host.personId);
                        rec.set("requesterName", defaultRoute.host.name);
                    }
                } else {
                    //user is an employee
                    rec.set("requesterId", userId);
                }
            }

            //check if any modification is done
            if (rec.dirty) {
                //compare the change to see if there's a need to update the route
                //if original is request for self but change is request for someone else.
                updateRouteUrl = bcp.config.Runtime.getServerBaseUrl() + "routes/" + rec.data.routeId;

                if (rec.data.statusCode === 1 && rec.data.creatorId != rec.data.requesterId) {
                    needRouteUpdt = true;
                    routeObj.typeId = 0;
                    routeObj.notes = "";
                    routeObj.statusId = 12;
                    routeObj.routeTo = rec.data.creatorId;
                } else if (rec.data.statusCode === 12 && rec.data.creatorId == rec.data.requesterId) {
                    needRouteUpdt = true;
                    routeObj.typeId = 0;
                    routeObj.notes = "";
                    routeObj.statusId = 1;
                    routeObj.routeTo = rec.data.creatorId;
                }
            } else {
                return;
            }
        } else {
            //form has error
            Ext.Msg.alert("Form Validation Error", "One or more fields in the form are invalid.");
            return;
        }

        //if we need to update the route
        if (needRouteUpdt) {
            //update the route record first
            bcp.util.CommonUtil.makeAjaxRequest({
                url: updateRouteUrl,
                method: method,
                scope: me,
                jsonData: Ext.encode(routeObj) // Ext.Ajax handles encoding, but explicit is fine too
            })
                .then(me.updateReq(me, url, method, rec, currentUserDivId))
                .catch(function (error) {
                    Ext.Msg.alert("Failure", "The request was not updated.");
                    return;
                });
        } else {
            me.updateReq(me, url, method, rec, currentUserDivId);
        }
    },

    updateReq: function (me, url, method, rec, currentUserDivId) {
        //make sure when requester is changed, the DC is updated to the new requester's DC
        bcp.util.CommonFunctions.prepareDcRecord(rec, currentUserDivId).then(function (newRecord) {
            if (newRecord) {
                //update req
                rec.set("divisionChiefId", newRecord.get("routeTo"));
                rec.set("dcName", newRecord.get("routeToName"));
            }
            //then update the request record
            Ext.Ajax.request({
                url: url,
                method: method,
                scope: this,
                jsonData: Ext.encode(rec.data),
                success: function (response) {
                    bcp.util.CommonUtil.ajaxSuccessHandler(response, function (result) {
                        if (result.data) {
                            rec = Ext.create("bcp.model.BcpRequest", result.data);
                            me.redirectTo("#newrequest/" + rec.data.requestId);
                            return;
                        } else {
                            Ext.Msg.alert("Failure", "The request was not updated.");
                            return;
                        }
                    });
                }
            });
        });
    },

    onCancel: function (button, e, eOpts) {
        var requestId = this.getViewModel().get("record").data.requestId;
        this.redirectTo("#newrequest/" + requestId);
    },

    onWindowAdded: function (component, container, pos, eOpts) {
        var model = this.getViewModel(),
            rec = model.get("currentRequest"),
            user = model.get("loggedInUser"),
            refs = this.getReferences(),
            form = refs.form.getForm(),
            radioGrp = refs.requesterRg,
            onBehalfCombo = refs.onBehalfCombo;

        if (!rec || rec.data.requestId === 0) {
            this.redirectTo("#dashboard");
            return;
        }

        //if associates try to do it for someone else, that someone must be a fed
        if (user.staffType === "NIST Associate") {
            refs.selfRb.hide();
            refs.selfRb.disable();
            /*this requires a record in model and changes record value
            refs.requesterRg.setValue({
            whoVal : 'notme'
            });
            refs.onBehalfCombo.setValue(newRecord.get("requesterId"));
            */
        } else {
            refs.selfRb.show();
            refs.selfRb.enable();
            /*this requires a record in model and changes record value
            //cause change
            refs.requesterRg.setValue({
                whoVal : 'self'
            });
            */
        }

        if (rec.data.creatorId !== rec.data.requesterId) {
            radioGrp.setValue({whoVal: "notme"});
        } else {
            radioGrp.setValue({whoVal: "self"});
        }

        model.set("record", rec);

        // Set record
        form.loadRecord(rec);

        //for strange reason, the loadrecord above doesn't set value in this combo
        //so do it manually here
        onBehalfCombo.setValue(rec.data.requesterId);
    }
});
